13. use crate::{
14.     hal::mem::FrameAddress,
15.     mm::phys::{
16.         frame,
17.         kframe::KernelFrame,
18.         upool::{
19.             Upool,
20.             UserFrame,
21.         },
22.     },
23. };
24. use ::alloc::vec::Vec;
25. use ::arch::mem;
26. use ::core::{
27.     hint::unlikely,
28.     mem::MaybeUninit,
29.     sync::atomic::{
30.         AtomicBool,
31.         Ordering,
32.     },
33. };
34. use ::sys::error::{
35.     Error,
36.     ErrorCode,
37. };
38. use ::vstd::prelude::*;
39. 
40. //==================================================================================================
41. // Constants
42. //==================================================================================================
43. 
44. // Use relaxed ordering for all atomic operations to mitigate synchronization overhead. It is safe
45. // to use this ordering semantics because Nanvix is a single-core system, and the kernel runs with
46. // interrupts disabled.
47. const ORDER: Ordering = Ordering::Relaxed;
48. 
49. //==================================================================================================
50. // Global Variables
51. //==================================================================================================
52. 
53. /// Physical memory manager storage.
54. static mut PHYS_MEMORY_MANAGER: MaybeUninit<PhysMemoryManager> = MaybeUninit::uninit();
55. 
56. /// Whether the physical memory manager has been initialized.
57. static PHYS_MEMORY_MANAGER_INIT: AtomicBool = AtomicBool::new(false);
58. 
59. //==================================================================================================
60. // Structures
61. //==================================================================================================
62. 
63. ///
64. /// # Description
65. ///
66. /// Physical memory manager.
67. ///
68. #[verus_verify]
69. pub struct PhysMemoryManager {
70.     upool: Upool,
71. }
72. 
73. //==================================================================================================
74. // Implementations
75. //==================================================================================================
76. 
77. #[verus_verify]
78. impl PhysMemoryManager {
79.     ///
80.     /// # Description
81.     ///
82.     /// Initializes the physical memory manager singleton.
83.     ///
84.     /// # Parameters
85.     ///
86.     /// - `upool`: User page pool.
87.     ///
88.     /// # Errors
89.     ///
90.     /// Returns `InvalidArgument` if the singleton has already been initialized.
91.     ///
92.     // TCB: bringing up the manager singleton writes a `MaybeUninit` static behind an
93.     // `AtomicBool` flag — raw-memory/atomics operations outside Verus's model. On success the
94.     // manager layer becomes ready (`phys_view().manager_ready`); the frame partition is
95.     // untouched. Listed in `verus-ai-logs/tcb-allowed.md`.
96.     #[verus_spec(result =>
97.         ensures
98.             match result {
99.                 Ok(_) => crate::mm::phys::phys_view().manager_ready,
100.                 Err(_) => crate::mm::phys::phys_view().manager_ready,
101.             },
102.     )]
103.     pub(super) fn init(upool: Upool) -> Result<(), Error> {
104.         if unlikely(PHYS_MEMORY_MANAGER_INIT.load(ORDER)) {
105.             return Err(Error::new(
106.                 ErrorCode::InvalidArgument,
107.                 "physical memory manager already initialized",
108.             ));
109.         }
110. 
111.         // SAFETY: this happens during kernel initialization and no other threads are running.
112.         unsafe { PHYS_MEMORY_MANAGER.write(PhysMemoryManager { upool }) };
113.         PHYS_MEMORY_MANAGER_INIT.store(true, ORDER);
114.         Ok(())
115.     }
116. }
117. 
118. impl PhysMemoryManager {
119.     ///
120.     /// # Description
121.     ///
122.     /// Gets a mutable reference to the physical memory manager.
123.     ///
124.     /// # Panics
125.     ///
126.     /// Panics if the physical memory manager is not initialized.
127.     ///
128.     /// # Safety
129.     ///
130.     /// This function is unsafe because it returns a mutable reference to a global variable.
131.     ///
132.     /// The caller must ensure:
133.     ///
134.     /// - No other `&mut PhysMemoryManager` reference obtained from this function is live at the
135.     ///   same time (i.e., `&mut` references must not overlap). In practice this is guaranteed
136.     ///   because the kernel is single-threaded and runs with interrupts disabled, so no
137.     ///   re-entrant or concurrent call can alias the reference.
138.     ///
139.     pub unsafe fn get_mut<'a>() -> &'a mut PhysMemoryManager {
140.         if unlikely(!PHYS_MEMORY_MANAGER_INIT.load(ORDER)) {
141.             panic!("physical memory manager is not initialized");
142.         }
143. 
144.         // SAFETY: the physical memory manager has been initialized, so the value is valid.
145.         PHYS_MEMORY_MANAGER.assume_init_mut()
146.     }
147. }
148. 
149. #[verus_verify]
150. impl PhysMemoryManager {
151.     ///
152.     /// # Description
153.     ///
154.     /// Allocates user frames into caller-provided storage.
155.     ///
156.     /// The returned frames are not guaranteed to be physically contiguous.
157.     /// User allocations are gated by the kernel watermark: if fulfilling the request would
158.     /// leave fewer than `KERNEL_WATERMARK` free frames, the allocation is rejected.
159.     ///
160.     /// # Parameters
161.     ///
162.     /// - `count`: Number of frames to allocate.
163.     /// - `frames`: Mutable reference to a pre-allocated vector into which to store those
164.     ///   frames' addresses. It should have sufficient capacity for `count` entries.
165.     ///
166.     /// # Return Values
167.     ///
168.     /// Upon success, `Ok(())` is returned and `frames` is filled with `count` frames. Upon failure, an
169.     /// error is returned and any frames allocated by this call are dropped by truncating `frames`
170.     /// back to empty.
171.     ///
172.     #[verus_spec(result =>
173.         requires
174.             self.inv(),
175.             old(frames)@.len() == 0,
176.         ensures
177.             final(self).inv(),
178.             match result {
179.                 Ok(()) => {
180.                     &&& (count > 0 ==> old(self)@.user_alloc_ok(count as nat))
181.                     &&& final(frames)@.len() == count
182.                     &&& user_addr_set(final(frames)@).len() == count
183.                     &&& old(self)@.all_free(user_addr_set(final(frames)@))
184.                     &&& final(self)@ == old(self)@.book_all(user_addr_set(final(frames)@))
185.                 },
186.                 Err(_) => {
187.                     &&& final(self)@ == old(self)@
188.                     &&& final(frames)@.len() == 0
189.                 },
190.             },
191.     )]
192.     pub fn alloc_many_user_frames(
193.         &mut self,
194.         count: usize,
195.         frames: &mut Vec<UserFrame>,
196.     ) -> Result<(), Error> {
197.         proof_decl! {
198.             let ghost g_old = self@;
199.         }
200.         proof! {
201.             assert(g_old == old(self)@);
202.             assert(g_old.wf());
203.         }
204.         if !frames.is_empty() {
205.             let reason: &str = "frames vector is not empty";
206.             #[cfg(not(verus_keep_ghost))]
207.             error!("{reason}");
208.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
209.         }
210.         if frames.capacity() < count {
211.             let reason: &str = "frames vector has insufficient capacity";
212.             #[cfg(not(verus_keep_ghost))]
213.             error!("{reason}");
214.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
215.         }
216. 
217.         // A zero-sized allocation is trivially satisfied.
218.         if count == 0 {
219.             proof! {
220.                 lemma_user_bulk_ok(g_old, self@, frames@, count as nat);
221.             }
222.             return Ok(());
223.         }
224. 
225.         Self::check_user_watermark(count)?;
226.         proof! {
227.             lemma_manager_attached(self);
228.         }
229. 
230.         #[cfg_attr(verus_keep_ghost, verus_spec(
231.             invariant
232.                 g_old == old(self)@,
233.                 g_old.wf(),
234.                 self@.wf(),
235.         ))]
236.         for _ in 0..count {
237.             match self.upool.alloc() {
238.                 Ok(frame) => frames.push(frame),
239.                 Err(error) => {
240.                     frames.clear();
241.                     proof! {
242.                         lemma_user_bulk_err_restored(self, g_old);
243.                     }
244.                     return Err(error);
245.                 },
246.             }
247.         }
248.         proof! {
249.             lemma_user_bulk_ok(g_old, self@, frames@, count as nat);
250.         }
251.         Ok(())
252.     }
253. 
254.     ///
255.     /// # Description
256.     ///
257.     /// Allocates a single user frame, applying the same kernel watermark check as
258.     /// [`Self::alloc_many_user_frames`]. This is the single-frame fast path used on
259.     /// hot paths such as copy-on-write fault resolution, where allocating an
260.     /// intermediate [`Vec`] would be wasteful.
261.     ///
262.     /// # Returns
263.     ///
264.     /// Upon success, a [`UserFrame`] is returned. Upon failure, an error is returned
265.     /// instead.
266.     ///
267.     #[verus_spec(result =>
268.         requires
269.             self.inv(),
270.         ensures
271.             final(self).inv(),
272.             match result {
273.                 Ok(uf) => {
274.                     &&& old(self)@.user_alloc_ok(1)
275.                     &&& old(self)@.free_frames.contains(uf@)
276.                     &&& final(self)@ == old(self)@.alloc_one(uf@)
277.                 },
278.                 Err(_) => {
279.                     &&& final(self)@ == old(self)@
280.                     &&& !old(self)@.user_alloc_ok(1)
281.                 },
282.             },
283.     )]
284.     pub fn alloc_user_frame(&mut self) -> Result<UserFrame, Error> {
285.         proof! {
286.             lemma_manager_attached(self);
287.         }
288.         Self::check_user_watermark(1)?;
289.         self.upool.alloc()
290.     }
291. 
292.     ///
293.     /// # Description
294.     ///
295.     /// Rejects user allocations of `count` frames that would breach the kernel
296.     /// watermark, i.e. that would drop the number of free frames below
297.     /// [`config::kernel::KERNEL_WATERMARK`].
298.     ///
299.     /// # Parameters
300.     ///
301.     /// - `count`: Number of user frames the caller intends to allocate.
302.     ///
303.     /// # Returns
304.     ///
305.     /// Upon success, `Ok(())` is returned. Upon failure, an error is returned instead.
306.     ///
307.     #[verus_spec(result =>
308.         ensures
309.             match result {
310.                 Ok(()) => crate::mm::phys::phys_view().frames.free_count()
311.                     >= count as nat + spec_kernel_watermark(),
312.                 Err(_) => crate::mm::phys::phys_view().frames.free_count()
313.                     < count as nat + spec_kernel_watermark(),
314.             },
315.     )]
316.     fn check_user_watermark(count: usize) -> Result<(), Error> {
317.         proof! {
318.             lemma_free_count_bounded();
319.         }
320.         let watermark_threshold: usize = kernel_watermark()
321.             .checked_add(count)
322.             .ok_or_else(|| {
323.                 let reason: &str = "watermark + count overflow";
324.                 #[cfg(not(verus_keep_ghost))]
325.                 error!("{reason}");
326.                 Error::new(ErrorCode::InvalidArgument, reason)
327.             })?;
328.         if frame::free_count() < watermark_threshold {
329.             let reason: &str = "would breach kernel watermark";
330.             #[cfg(not(verus_keep_ghost))]
331.             error!("{reason}");
332.             return Err(Error::new(ErrorCode::OutOfMemory, reason));
333.         }
334.         Ok(())
335.     }
336. 
337.     ///
338.     /// # Description
339.     ///
340.     /// Allocates a kernel frame.
341.     ///
342.     /// Kernel allocations bypass the watermark — no artificial ceiling.
343.     ///
344.     /// # Return Values
345.     ///
346.     /// Upon success, a kernel frame is returned. Upon failure, an error is returned instead.
347.     ///
348.     #[verus_spec(result =>
349.         requires
350.             self.inv(),
351.         ensures
352.             final(self).inv(),
353.             match result {
354.                 Ok(kf) => {
355.                     &&& old(self)@.free_frames.contains(kf@)
356.                     &&& final(self)@ == old(self)@.alloc_one(kf@)
357.                 },
358.                 Err(_) => final(self)@ == old(self)@,
359.             },
360.     )]
361.     pub fn alloc_kernel_frame(&mut self) -> Result<KernelFrame, Error> {
362.         proof_decl! {
363.             let ghost g_old = self@;
364.         }
365.         let frame_addr: FrameAddress = frame::alloc()?;
366.         let result: Result<KernelFrame, Error> = KernelFrame::new(frame_addr).inspect_err(|e| {
367.             #[cfg(not(verus_keep_ghost))]
368.             warn!("failed to wrap frame after KernelFrame::new failure: {e:?}");
369.             if let Err(free_err) = frame::free(frame_addr) {
370.                 #[cfg(not(verus_keep_ghost))]
371.                 warn!("failed to free frame after KernelFrame::new failure: {free_err:?}");
372.             }
373.         });
374.         proof! {
375.             if result is Ok {
376.                 lemma_kernel_alloc_one(g_old, self@, result->Ok_0@);
377.             }
378.         }
379.         result
380.     }
381. 
382.     ///
383.     /// # Description
384.     ///
385.     /// Allocates a contiguous range of kernel frames into caller-provided storage.
386.     ///
387.     /// Kernel stacks require physically contiguous frames because the kernel uses identity
388.     /// mapping and the hardware stack pointer traverses the region linearly.
389.     /// Kernel allocations bypass the watermark — no artificial ceiling.
390.     ///
391.     /// # Parameters
392.     ///
393.     /// - `count`: Number of frames to allocate.
394.     /// - `frames`: Mutable reference to a pre-allocated vector into which to store
395.     ///   those frames' addresses.
396.     ///
397.     /// # Return Values
398.     ///
399.     /// Upon success, `Ok(())` is returned and `frames` is filled with `count`
400.     /// contiguous entries. Upon failure, an error is returned instead.
401.     ///
402.     #[verus_spec(result =>
403.         requires
404.             self.inv(),
405.             old(frames)@.len() == 0,
406.             count > 0,
407.         ensures
408.             final(self).inv(),
409.             match result {
410.                 Ok(()) => {
411.                     &&& final(frames)@.len() == count
412.                     &&& kernel_frames_contiguous(final(frames)@, count as nat)
413.                     &&& old(self)@.all_free(kernel_addr_set(final(frames)@))
414.                     &&& final(self)@ == old(self)@.book_all(kernel_addr_set(final(frames)@))
415.                 },
416.                 Err(_) => {
417.                     &&& final(self)@ == old(self)@
418.                     &&& final(frames)@.len() == 0
419.                 },
420.             },
421.     )]
422.     pub fn alloc_many_kernel_frames(
423.         &mut self,
424.         count: usize,
425.         frames: &mut Vec<KernelFrame>,
426.     ) -> Result<(), Error> {
427.         proof_decl! {
428.             let ghost g_old = self@;
429.         }
430.         proof! {
431.             assert(g_old == old(self)@);
432.             assert(g_old.wf());
433.         }
434.         // Check if caller-provided vector is not empty.
435.         if !frames.is_empty() {
436.             let reason: &str = "frames vector is not empty";
437.             #[cfg(not(verus_keep_ghost))]
438.             error!("{reason}");
439.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
440.         }
441.         if frames.capacity() < count {
442.             let reason: &str = "frames vector has insufficient capacity";
443.             #[cfg(not(verus_keep_ghost))]
444.             error!("{reason}");
445.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
446.         }
447. 
448.         let base_addr: FrameAddress = frame::alloc_contiguous(count)?;
449.         let base_raw: usize = base_addr.into_raw_value();
450.         #[cfg_attr(verus_keep_ghost, verus_spec(
451.             invariant
452.                 g_old == old(self)@,
453.                 g_old.wf(),
454.                 self@ == g_old,
455.                 base_raw as int == base_addr@,
456.                 base_raw as int + (count as int) * spec_page_size() <= usize::MAX as int,
457.         ))]
458.         for i in 0..count {
459.             proof! {
460.                 lemma_contig_no_overflow(base_raw, i, count);
461.             }
462.             let raw_addr: usize = base_raw + i * mem::PAGE_SIZE;
463.             match FrameAddress::from_raw_value(raw_addr).and_then(KernelFrame::new) {
464.                 Ok(kf) => frames.push(kf),
465.                 Err(e) => {
466.                     // Drop already-wrapped frames (frees them via KernelFrame::Drop).
467.                     frames.clear();
468.                     // Free remaining un-wrapped frames from the contiguous allocation.
469.                     #[cfg_attr(verus_keep_ghost, verus_spec(
470.                         invariant
471.                             g_old == old(self)@,
472.                             g_old.wf(),
473.                             self@ == g_old,
474.                             base_raw as int == base_addr@,
475.                             base_raw as int + (count as int) * spec_page_size()
476.                                 <= usize::MAX as int,
477.                     ))]
478.                     for j in i..count {
479.                         proof! {
480.                             lemma_contig_no_overflow(base_raw, j, count);
481.                         }
482.                         let leak_raw: usize = base_raw + j * mem::PAGE_SIZE;
483.                         if let Ok(fa) = FrameAddress::from_raw_value(leak_raw) {
484.                             if let Err(e) = frame::free(fa) {
485.                                 #[cfg(not(verus_keep_ghost))]
486.                                 warn!("failed to free leaked frame {fa:?}: {e:?}");
487.                             }
488.                         }
489.                     }
490.                     return Err(e);
491.                 },
492.             }
493.         }
494.         proof! {
495.             lemma_kernel_alloc_contiguous(g_old, self@, frames@, count as nat);
496.         }
497.         Ok(())
498.     }
499. }
500. 
501. //==================================================================================================
502. // Build-time constant accessors
503. //==================================================================================================
504. 
505. // External-bottom trust boundary: `config::kernel::KERNEL_WATERMARK` is generated by the `config`
506. // crate's `build.rs` (from `kernel_config.toml`) and lives in a non-Verus dependency crate, so
507. // Verus cannot resolve its value. This accessor ties the runtime constant to the abstract
508. // `spec_kernel_watermark()`. Listed in `verus-ai-logs/tcb-allowed.md`.
509. #[verus_spec(ret =>
510.     ensures
511.         ret as nat == spec_kernel_watermark(),
512. )]
513. fn kernel_watermark() -> usize {
514.     config::kernel::KERNEL_WATERMARK
515. }
516.

