         pre.wf(),
     ensures
         frames.len() == count,
         crate::mm::phys::manager::kernel_frames_contiguous(frames, count),
         post == pre.book_all(crate::mm::phys::manager::kernel_addr_set(frames)),
         pre.all_free(crate::mm::phys::manager::kernel_addr_set(frames)),
         post.wf(),
 {
     admit();
 }

